      [[`Car (Ackermann)`, `Voiture (Ackermann)`], [`R<sub>min</sub> = e / tan δ<sub>max</sub> ≈ 1 m or more: it cannot turn around in a 1.5 m corridor.`, `R<sub>min</sub> = e / tan δ<sub>max</sub> ≈ 1 m ou plus : il ne peut pas faire demi-tour dans un couloir de 1,5 m.`], [`✗`, `✗`]],
      [[`Mecanum / omni`, `Mecanum / omni`], [`holonomic, but poor odometry, floor must be good, more wear; sideways is not required.`, `holonome, mais mauvaise odométrie, sol à bon état exigé, plus d'usure ; le déplacement latéral n'est pas demandé.`], [`not needed`, `pas nécessaire`]],
      [[`Differential (2 drive wheels + castors)`, `Différentiel (2 roues motrices + roulettes)`], [`spins on the spot (R<sub>min</sub> = 0), 2 motors, accurate odometry, simple.`, `tourne sur place (R<sub>min</sub> = 0), 2 moteurs, odométrie précise, simple.`], [`<strong>✓ chosen</strong>`, `<strong>✓ choisi</strong>`]]
